<?php require_once '../includes/auth.php';require_once '../config/uploads.php';login_required();$s=store();if(!$s)go('/seller/store.php');$q=$pdo->prepare('SELECT * FROM products WHERE store_id=? ORDER BY created_at DESC');$q->execute([$s['id']]);$ps=$q->fetchAll();$title='Products';require '../includes/header.php';?><div class="d-flex justify-content-between"><h1>Products</h1><a class="btn btn-success" href="/seller/add-product.php">Add product</a></div><div class="row g-3"><?php foreach($ps as $p):?><div class="col-md-4"><div class="card h-100"><?php if($p['image']):?><img class="card-img-top" style="height:180px;object-fit:cover" src="<?=e($uploadUrl . '/' . $p['image'])?>" alt="<?=e($p['name'])?>"><?php endif;?><div class="card-body"><h5><?=e($p['name'])?></h5><p><?=e($p['category'])?> · <?=money($p['price'])?></p><span class="badge bg-secondary"><?=e($p['moderation_status']??'pending')?></span> <span class="badge bg-success"><?= $p['available']?'Available':'Unavailable'?></span><?php if(!empty($p['moderation_note'])):?><p class="small text-muted mt-2"><?=e($p['moderation_note'])?></p><?php endif;?></div></div></div><?php endforeach;?></div><?php require '../includes/footer.php';?>